package com.aegis.erp.modules.planilla.inasistencia;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import com.aegis.erp.common.exception.BusinessConflictException;import com.aegis.erp.common.export.DocumentExportService;import com.aegis.erp.modules.planilla.entity.*;import com.aegis.erp.modules.planilla.repository.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;
@ExtendWith(MockitoExtension.class)class InasistenciaServiceTest{@Mock InasistenciaRepository repo;@Mock EmpleadoRepository empleados;@Mock DocumentExportService exports;InasistenciaService service;@BeforeEach void setup(){service=new InasistenciaService(repo,empleados,exports,Clock.fixed(Instant.parse("2026-09-22T12:00:00Z"),ZoneOffset.UTC));}@Test void rechazaRangoInvertido(){assertThrows(BusinessConflictException.class,()->service.crear(new InasistenciaRequest(1L,LocalDateTime.of(2026,2,2,8,0),LocalDateTime.of(2026,2,1,8,0),null),"admin"));verifyNoInteractions(empleados);}@Test void permiteCruzarMesYSinProcesar(){Empleado e=empleado();when(empleados.findById(1L)).thenReturn(Optional.of(e));when(repo.saveAndFlush(any())).thenAnswer(i->i.getArgument(0));var out=service.crear(new InasistenciaRequest(1L,LocalDateTime.of(2026,1,31,8,0),LocalDateTime.of(2026,2,2,17,0)," Viaje "),"admin");assertNull(out.fechaProcesado());ArgumentCaptor<Inasistencia>c=ArgumentCaptor.forClass(Inasistencia.class);verify(repo).saveAndFlush(c.capture());assertNull(c.getValue().getFechaProcesado());assertEquals("Viaje",c.getValue().getMotivo());assertEquals("admin",c.getValue().getUsuarioCreacion());}private Empleado empleado(){Empleado e=mock(Empleado.class);Persona p=mock(Persona.class);when(e.getId()).thenReturn(1L);when(e.getPersona()).thenReturn(p);when(p.getNombre()).thenReturn("Ana");when(p.getApellido()).thenReturn("López");return e;}}
